create table public.marketing_topics(topic_id integer primary key,title_en text not null,title_hi text not null,body_en text not null,body_hi text not null);
create table public.marketing_posts(
 id uuid primary key default gen_random_uuid(),day date unique not null,topic_id integer references public.marketing_topics(topic_id),
 title_en text not null check(length(title_en)<=140),title_hi text not null check(length(title_hi)<=140),
 body_en text not null check(length(body_en)<=700),body_hi text not null check(length(body_hi)<=700),
 palette integer not null check(palette between 0 and 3),layout integer not null check(layout between 0 and 2),
 state text not null default 'draft' check(state in ('draft','approved','archived')),updated_by uuid references auth.users(id),
 updated_at timestamptz not null default now(),revision integer not null default 1
);
alter table public.marketing_topics enable row level security;
alter table public.marketing_posts enable row level security;
revoke all on public.marketing_topics,public.marketing_posts from public,anon,authenticated;
grant all on public.marketing_topics,public.marketing_posts to service_role;
create policy marketing_topics_service_only on public.marketing_topics for all to service_role using(true) with check(true);
create policy marketing_posts_service_only on public.marketing_posts for all to service_role using(true) with check(true);
insert into public.marketing_topics select * from jsonb_to_recordset($topics$[{"topic_id":1,"title_en":"Count a purchase once","title_hi":"खर्च एक बार गिनें","body_en":"If groceries are already in your monthly totals, adding the full card bill can count the same purchase again. Separate old debt repayment from new purchases.","body_hi":"राशन पहले खर्च में जोड़ा है तो पूरा कार्ड बिल जोड़ने से वही खरीद दोबारा गिन सकती है। पुराने कर्ज़ की वापसी और नई खरीद अलग समझें।"},{"topic_id":2,"title_en":"Small EMI, longer commitment","title_hi":"छोटी EMI, लंबी ज़िम्मेदारी","body_en":"Compare the number of instalments and the full payment total. A lower monthly EMI can still cost more overall.","body_hi":"किस्तों की संख्या और कुल भुगतान साथ देखें। महीने की छोटी EMI का कुल खर्च फिर भी ज़्यादा हो सकता है।"},{"topic_id":3,"title_en":"Make room for annual bills","title_hi":"सालाना बिल की जगह रखें","body_en":"An approximate monthly budget can miss yearly insurance, repairs or school costs. Note irregular needs before calling the remaining amount spare money.","body_hi":"लगभग बजट में सालाना बीमा, मरम्मत या स्कूल का खर्च छूट सकता है। बची रकम को खाली मानने से पहले अनियमित ज़रूरतें लिखें।"},{"topic_id":4,"title_en":"Minimum due is not full repayment","title_hi":"न्यूनतम देय पूरा भुगतान नहीं","body_en":"Read your card statement and issuer terms. Interest, fees and payment allocation vary; the minimum due is not a universal fixed EMI.","body_hi":"कार्ड स्टेटमेंट और बैंक की शर्तें पढ़ें। ब्याज, शुल्क और भुगतान का बँटवारा अलग हो सकता है; न्यूनतम देय एक तय EMI नहीं है।"},{"topic_id":5,"title_en":"UPI pending? Check status first","title_hi":"UPI अटका? पहले स्थिति देखें","body_en":"Open the transaction inside the app and use its official help option. Do not assume pending means failed and repeat the payment without checking.","body_hi":"ऐप में लेन-देन खोलकर उसका आधिकारिक सहायता विकल्प देखें। जाँच किए बिना अटके भुगतान को असफल मानकर दोबारा भुगतान न करें।"},{"topic_id":6,"title_en":"A refund does not need your PIN","title_hi":"रिफंड के लिए PIN न दें","body_en":"Keep OTPs and UPI PINs private. Someone claiming to send a refund should not ask you to share a PIN or give remote access.","body_hi":"OTP और UPI PIN निजी रखें। धनवापसी भेजने के नाम पर PIN साझा करने या फोन का रिमोट एक्सेस देने की ज़रूरत नहीं है।"},{"topic_id":7,"title_en":"Compare like with like","title_hi":"एक जैसी चीज़ें तुलना करें","body_en":"Two purchase quotes may include different insurance, accessories or warranty. Match the inclusions before comparing the final total.","body_hi":"खरीद के दो कोटेशन में बीमा, सामान या वारंटी अलग हो सकते हैं। कुल रकम की तुलना से पहले सुविधाएँ मिलाएँ।"},{"topic_id":8,"title_en":"A reward can have conditions","title_hi":"रिवॉर्ड की शर्तें होती हैं","body_en":"Check eligible spending, caps, exclusions, fees and expiry. A possible reward is different from a cash discount available today.","body_hi":"पात्र खर्च, सीमा, अपवाद, शुल्क और समाप्ति देखें। संभावित रिवॉर्ड और आज की नकद छूट अलग हैं।"},{"topic_id":9,"title_en":"Start with rough monthly totals","title_hi":"लगभग हिसाब से शुरुआत करें","body_en":"You do not need to log every daily purchase to start. Use honest category estimates and note what you have left out.","body_hi":"शुरुआत के लिए हर दिन की खरीद लिखना ज़रूरी नहीं। श्रेणियों में ईमानदार अनुमान भरें और छूटे खर्च पहचानें।"},{"topic_id":10,"title_en":"Variable income needs scenarios","title_hi":"अनियमित आय में अलग अनुमान","body_en":"Try a cautious month and a typical month separately. Do not treat an unusually good month as guaranteed future income.","body_hi":"कम आय वाले और सामान्य महीने का अलग हिसाब देखें। बहुत अच्छे महीने की कमाई को आगे की गारंटी न मानें।"},{"topic_id":11,"title_en":"Check recurring subscriptions","title_hi":"दोहराते भुगतान जाँचें","body_en":"Review subscriptions and automatic renewals in your own app or statements. Check cancellation terms before making changes.","body_hi":"अपने ऐप या स्टेटमेंट में सदस्यता और अपने आप होने वाले नवीनीकरण देखें। बदलाव से पहले रद्द करने की शर्तें पढ़ें।"},{"topic_id":12,"title_en":"Keep the complaint reference","title_hi":"शिकायत संख्या सँभालें","body_en":"For a payment issue, keep the official complaint reference and response privately. It helps you track the case without posting bank details publicly.","body_hi":"भुगतान की दिक्कत में आधिकारिक शिकायत संख्या और जवाब निजी रखें। इससे बैंक विवरण सार्वजनिक किए बिना मामला समझने में मदद मिलती है।"},{"topic_id":13,"title_en":"ITR is not an approval guarantee","title_hi":"ITR मंज़ूरी की गारंटी नहीं","body_en":"Issuer eligibility differs. A past tax return alone does not establish current income, repayment capacity or a guaranteed card approval.","body_hi":"हर बैंक की पात्रता अलग होती है। पुराना ITR अकेले वर्तमान आय, भुगतान की क्षमता या कार्ड की मंज़ूरी तय नहीं करता।"},{"topic_id":14,"title_en":"Understand an FD lien","title_hi":"FD पर lien समझें","body_en":"Before considering an FD-backed card, check access to the deposit, the lien, fees and repayment terms. Keep emergency needs in view.","body_hi":"FD-backed कार्ड से पहले जमा रकम की उपलब्धता, lien, शुल्क और भुगतान की शर्तें देखें। आपातकालीन ज़रूरतें भी ध्यान में रखें।"},{"topic_id":15,"title_en":"Read the written quote","title_hi":"लिखित कोटेशन पढ़ें","body_en":"Ask which charges are included, which are separate and whether a final payment remains. A headline offer is not the complete agreement.","body_hi":"पूछें कौन से शुल्क शामिल हैं, कौन से अलग हैं और क्या आखिरी भुगतान बाकी है। हेडलाइन ऑफ़र पूरा समझौता नहीं है।"},{"topic_id":16,"title_en":"Unknown charge? Use official support","title_hi":"अनजान शुल्क? सही मदद लें","body_en":"Check the statement description and your records. Use the bank’s official dispute or support channel; do not share credentials with strangers.","body_hi":"स्टेटमेंट का विवरण और अपने रिकॉर्ड देखें। बैंक के आधिकारिक सहायता/विवाद विकल्प का उपयोग करें; अनजान व्यक्ति को लॉगिन विवरण न दें।"},{"topic_id":17,"title_en":"A link is optional","title_hi":"लिंक का उपयोग वैकल्पिक है","body_en":"An affiliate link may benefit the website. Read the disclosure and partner terms; commission does not prove the product fits your needs.","body_hi":"एफ़िलिएट लिंक से वेबसाइट को लाभ मिल सकता है। खुलासा और पार्टनर की शर्तें पढ़ें; कमीशन उत्पाद की उपयुक्तता साबित नहीं करता।"},{"topic_id":18,"title_en":"Approval and rewards are different","title_hi":"मंज़ूरी और रिवॉर्ड अलग हैं","body_en":"An application, an approved account and an eligible reward are separate steps. Check what the programme actually counts before expecting a benefit.","body_hi":"आवेदन, स्वीकृत खाता और पात्र रिवॉर्ड अलग चरण हैं। लाभ की उम्मीद से पहले कार्यक्रम में क्या गिना जाता है, समझें।"},{"topic_id":19,"title_en":"Keep essentials in the picture","title_hi":"ज़रूरी खर्च साथ देखें","body_en":"A cheaper overall payment schedule can still be difficult every month. Review essentials and existing commitments before a new obligation.","body_hi":"कम कुल भुगतान वाला विकल्प भी हर महीने मुश्किल हो सकता है। नई ज़िम्मेदारी से पहले ज़रूरी खर्च और पुराने भुगतान देखें।"},{"topic_id":20,"title_en":"Do not double-count a financed fee","title_hi":"जुड़ा शुल्क दोबारा न जोड़ें","body_en":"If a fee is already included in scheduled EMIs, adding it again as a separate charge inflates your estimate. Check the quote breakdown.","body_hi":"शुल्क तय EMI में पहले से शामिल हो तो अलग से जोड़ने पर अनुमान बढ़ जाएगा। कोटेशन का बँटवारा जाँचें।"},{"topic_id":21,"title_en":"Check saving-account conditions","title_hi":"बचत खाते की शर्तें देखें","body_en":"Review balance requirements, charges and service conditions on the bank’s official page. A promotional benefit is not the whole account cost.","body_hi":"बैंक की आधिकारिक वेबसाइट पर बैलेंस की शर्तें, शुल्क और सेवाएँ देखें। प्रचार का लाभ खाते का पूरा खर्च नहीं बताता।"},{"topic_id":22,"title_en":"Use the right interest unit","title_hi":"ब्याज की इकाई जाँचें","body_en":"A monthly rate and an annual rate are different inputs. Check how the lender describes interest and whether other fees are included.","body_hi":"महीने की और साल की ब्याज दर अलग इनपुट हैं। ऋणदाता ने दर किस तरह बताई है और शुल्क शामिल हैं या नहीं, जाँचें।"},{"topic_id":23,"title_en":"A budget shortfall needs attention","title_hi":"बजट का घाटा समझें","body_en":"If entered spending exceeds income, review essentials and flexible costs. A new loan or reward offer does not itself remove the shortfall.","body_hi":"दर्ज खर्च आय से अधिक हो तो ज़रूरी और बदल सकने वाले खर्च देखें। नया लोन या रिवॉर्ड ऑफ़र अपने आप घाटा नहीं मिटाता।"},{"topic_id":24,"title_en":"Do not send financial records to chat","title_hi":"वित्तीय रिकॉर्ड चैट में न दें","body_en":"Use calculator fields for rough amounts. Never paste full account numbers, card details, PAN, OTPs or bank-login credentials into a help chat.","body_hi":"लगभग रकम कैलकुलेटर में भरें। पूरा खाता/कार्ड नंबर, PAN, OTP या बैंक लॉगिन किसी मदद वाली चैट में न डालें।"},{"topic_id":25,"title_en":"Keep payment dates visible","title_hi":"भुगतान की तारीख सामने रखें","body_en":"List upcoming commitments from your current statements. A tool result does not change contractual due dates or your payment obligations.","body_hi":"वर्तमान स्टेटमेंट से आने वाले भुगतान लिखें। टूल का नतीजा तय देय तारीख या भुगतान की ज़िम्मेदारी नहीं बदलता।"},{"topic_id":26,"title_en":"Read prepayment conditions first","title_hi":"अतिरिक्त भुगतान की शर्तें पढ़ें","body_en":"Before paying extra on a loan, confirm the lender’s process and applicable charges. Do not assume every loan has identical conditions.","body_hi":"लोन में अतिरिक्त रकम देने से पहले ऋणदाता की प्रक्रिया और लागू शुल्क जाँचें। हर लोन की शर्तें एक जैसी न मानें।"},{"topic_id":27,"title_en":"A balance is not a spending target","title_hi":"बची रकम खर्च का लक्ष्य नहीं","body_en":"Your result reflects only entered costs. Set aside what you need for omitted bills, reserves and personal goals before considering new spending.","body_hi":"नतीजा सिर्फ़ दर्ज खर्च दिखाता है। नया खर्च सोचने से पहले छूटे बिल, रिज़र्व और अपने लक्ष्यों की रकम देखें।"},{"topic_id":28,"title_en":"Check who operates the link","title_hi":"लिंक किसका है, जाँचें","body_en":"Before applying through a commercial link, check the destination and official programme terms. Keep documents within the official secure process.","body_hi":"व्यावसायिक लिंक से आवेदन से पहले वेबसाइट और आधिकारिक कार्यक्रम की शर्तें जाँचें। दस्तावेज़ केवल आधिकारिक सुरक्षित प्रक्रिया में दें।"},{"topic_id":29,"title_en":"Review when circumstances change","title_hi":"स्थिति बदले तो फिर देखें","body_en":"A budget or product comparison made earlier may no longer fit. Recheck when income, fees, household needs or commitments change.","body_hi":"पहले बनाया बजट या उत्पाद तुलना अब सही न हो सकती है। आय, शुल्क, घर की ज़रूरत या भुगतान बदलें तो दोबारा जाँचें।"},{"topic_id":30,"title_en":"Useful guidance has clear limits","title_hi":"उपयोगी जानकारी की सीमा साफ़ हो","body_en":"Look for assumptions, sources and review dates. Be cautious of guaranteed approvals, guaranteed savings or promises that hide conditions.","body_hi":"मान्यताएँ, स्रोत और समीक्षा की तारीख देखें। पक्की मंज़ूरी, तय बचत या छिपी शर्तों वाले वादों से सावधान रहें।"}]$topics$::jsonb) as x(topic_id integer,title_en text,title_hi text,body_en text,body_hi text);
create function public.create_daily_marketing_draft() returns uuid language plpgsql security invoker set search_path='' as $$
declare selected public.marketing_topics;current_day date:=(now() at time zone 'Asia/Kolkata')::date;day_number integer;created uuid;
begin
 day_number:=extract(doy from current_day)::integer;
 select * into selected from public.marketing_topics order by topic_id offset mod(day_number,(select count(*)::integer from public.marketing_topics)) limit 1;
 insert into public.marketing_posts(day,topic_id,title_en,title_hi,body_en,body_hi,palette,layout)
 values(current_day,selected.topic_id,selected.title_en,selected.title_hi,selected.body_en,selected.body_hi,mod(day_number,4),mod(day_number,3))
 on conflict(day) do nothing returning id into created;
 return created;
end $$;
create function private.audit_marketing_change() returns trigger language plpgsql security definer set search_path='' as $$
declare actor text;
begin
 select username into actor from public.admin_accounts where user_id=new.updated_by and enabled and role='owner';
 if actor is null then raise exception 'An enabled owner is required'; end if;
 new.revision:=old.revision+1;new.updated_at:=now();
 insert into public.admin_activity(actor_id,actor_username,action,target,details) values(new.updated_by,actor,'marketing.reviewed',new.id::text,jsonb_build_object('state',new.state,'day',new.day));
 return new;
end $$;
revoke all on function private.audit_marketing_change() from public,anon,authenticated;
create trigger audit_marketing_change before update on public.marketing_posts for each row execute function private.audit_marketing_change();
revoke all on function public.create_daily_marketing_draft() from public,anon,authenticated;
grant execute on function public.create_daily_marketing_draft() to service_role;
select public.create_daily_marketing_draft();
